private TreeNode<T> rotateRight(TreeNode<T> node) {
    // get left node
    TreeNode<T> left = node.left;
    // get left-right node
    TreeNode<T> leftRight = left.right;
    // left-right node takes node's place
    node.left = leftRight;
    // node becomes left's right child
    left.right = node;
    // update heights
    node.height = 1 + Math.max(height(node.left), height(node.right));
    left.height = 1 + Math.max(height(left.left), height(left.right));
    // return new parent
    return left;
}
