public class TimeBucket {
    private static final java.util.Date BASE_YEAR_BEGIN = new Date();

    /**
     * Compresses the given time bucket to a new time bucket according to the given day step.
     *
     * @param timeBucket the time bucket to compress
     * @param dayStep the day step to compress by
     * @return the compressed time bucket
     */
    static long compressTimeBucket(long timeBucket, int dayStep) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTimeInMillis(timeBucket);
        int dayOfMonth = calendar.get(Calendar.DAY_OF_MONTH);
        int compressDays = (dayOfMonth - 1) % dayStep;
        calendar.add(Calendar.DAY_OF_MONTH, -1 * compressDays);
        return calendar.getTimeInMillis();
    }
}
