private List<Integer> getShardingKeyIndicesForModel(String modelName) {
    // Get the list of fields for the model
    List<Field> fields = getFieldsForModel(modelName);

    // Get the list of field names that are part of the sharding key
    List<String> shardingKeyFieldNames = getShardingKeyFieldNamesForModel(modelName);

    // Find the indices of the sharding key fields in the list of fields
    List<Integer> shardingKeyIndices = new ArrayList<>();
    for (int i = 0; i < fields.size(); i++) {
        if (shardingKeyFieldNames.contains(fields.get(i).getName())) {
