public byte[] base64Decode(String s) {
    // initialize the byte array with the decoded length
    byte[] bytes = new byte[s.length() * 3 / 4];

    // loop through the input string and decode each character
    for (int i = 0; i < s.length(); i += 4) {
        // Each 4-character block is translated into 3 bytes.
        // The first 6 bits of the first byte and the last 2 bits of the second byte are unused and set to 0.
        bytes[i / 4 * 3] = (byte) ((hexCharToDigit(s.charAt(i)) << 2) + (hexCharToDigit(s.charAt(i + 1)) >> 2));
